"use client"

import * as React from "react"
import { createPortal } from "react-dom"

import { useComposedRefs } from "@/lib/0db/refs"
import { cn } from "@/lib/utils"
import { Dialog, DialogSurface, DialogTrigger, useDialog } from "@/components/ui/dialog"

const subscribe = () => () => {}
const onClient = () => true
const onServer = () => false

function Curtain(props: React.ComponentProps<typeof Dialog>) { return <Dialog {...props} /> }
const CurtainTrigger = DialogTrigger

type CurtainContentProps = React.ComponentProps<"dialog"> & { label?: string }

/** The page becomes the distant plane; the destinations come to the reading plane. */
function CurtainContent({ label = "Menu", className, children, ref: forwardedRef, ...props }: CurtainContentProps) {
  const { open, setOpen, titleId } = useDialog()
  const client = React.useSyncExternalStore(subscribe, onClient, onServer)
  const root = React.useRef<HTMLDialogElement>(null)
  const ref = useComposedRefs(root, forwardedRef)

  React.useEffect(() => {
    if (!client) return
    const dialog = root.current
    if (!dialog) return
    const marked = [...document.querySelectorAll<HTMLElement>("[data-curtain-page]")]
    const pages = (marked.length ? marked : [...document.body.children]).filter((el): el is HTMLElement => el instanceof HTMLElement && el !== dialog && !el.contains(dialog) && !el.matches("dialog, script, style, link"))
    const owned = pages.filter((el) => !el.hasAttribute("data-curtain-plane"))
    owned.forEach((el) => el.setAttribute("data-curtain-plane", ""))
    return () => owned.forEach((el) => { el.removeAttribute("data-curtain-plane"); el.removeAttribute("data-curtain-far") })
  }, [client])

  React.useEffect(() => {
    if (!client || !open) return
    const pages = [...document.querySelectorAll<HTMLElement>("[data-curtain-plane]")]
    const overflow = document.documentElement.style.overflow
    const bodyOverflow = document.body.style.overflow
    document.documentElement.style.overflow = "hidden"
    document.body.style.overflow = "hidden"
    pages.forEach((el) => el.setAttribute("data-curtain-far", ""))
    root.current?.querySelectorAll<HTMLElement>(".db-curtain-link").forEach((el, index) => el.style.setProperty("--db-curtain-order", String(index)))
    return () => {
      pages.forEach((el) => el.removeAttribute("data-curtain-far"))
      document.documentElement.style.overflow = overflow
      document.body.style.overflow = bodyOverflow
    }
  }, [open, client])

  if (!client) return null
  return createPortal(
    <DialogSurface ref={ref} data-slot="curtain" className={cn("db-curtain", className)} aria-describedby={undefined} {...props}>
      <div className="db-curtain-head">
        <h2 id={titleId} className="db-curtain-caption">{label}</h2>
        <button type="button" className="db-curtain-close" onClick={() => setOpen(false)} data-autofocus>Close</button>
      </div>
      <nav className="db-curtain-links" aria-label={label}>{children}</nav>
    </DialogSurface>, document.body,
  )
}

type CurtainLinkProps = React.ComponentProps<"a"> & { number?: string; description?: string }

function CurtainLink({ number, description, className, children, onClick, ...props }: CurtainLinkProps) {
  const { setOpen } = useDialog()
  return (
    <a data-slot="curtain-link" className={cn("db-curtain-link", className)} {...props} onClick={(event) => {
      onClick?.(event)
      if (!event.defaultPrevented && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey) setOpen(false)
    }}>
      {number && <span className="db-curtain-number">{number}</span>}
      <span className="db-curtain-name">{children}</span>
      {description && <span className="db-curtain-description db-reading">{description}</span>}
    </a>
  )
}

export { Curtain, CurtainTrigger, CurtainContent, CurtainLink, type CurtainContentProps, type CurtainLinkProps }

@layer components {
  /* WOVE: distance is scale and pencil. The destinations take the reading plane. */
  [data-curtain-plane] { transform-origin: 50% 0; transition: transform var(--db-andante) var(--db-exhale), color var(--db-andante); }
  [data-curtain-far] { transform: perspective(1000px) rotateX(5deg) translateZ(-100px) scale(0.94); color: var(--db-pencil); }
  [data-curtain-far], [data-curtain-far] * { --db-ink: var(--db-pencil); --db-graphite: var(--db-pencil); --db-accent: var(--db-pencil); }
  .db-curtain {
    position: fixed; inset: 0; inline-size: 100%; block-size: 100dvh; max-inline-size: none; max-block-size: none; margin: 0;
    padding: var(--db-space-6) var(--db-margin); border: 0; background: transparent; color: var(--db-ink); overflow: auto; overscroll-behavior: contain;
    opacity: 0; transition: opacity var(--db-andante), overlay var(--db-andante) allow-discrete, display var(--db-andante) allow-discrete;
  }
  .db-curtain[open] { opacity: 1; }
  .db-curtain::backdrop { background: var(--db-paper); opacity: 0; transition: opacity var(--db-andante), overlay var(--db-andante) allow-discrete, display var(--db-andante) allow-discrete; }
  .db-curtain[open]::backdrop { opacity: 1; }
  @starting-style { .db-curtain[open], .db-curtain[open]::backdrop { opacity: 0; } }
  .db-curtain-head { display: flex; align-items: baseline; justify-content: space-between; gap: var(--db-space-5); }
  .db-curtain-caption { font: inherit; font-size: var(--db-pp); color: var(--db-pencil); }
  .db-curtain-close { appearance: none; border: 0; background: none; color: var(--db-ink); font: inherit; cursor: pointer; padding: var(--db-space-3) 0; }
  .db-curtain-links { display: grid; gap: var(--db-space-5); margin-block: var(--db-space-7); }
  .db-curtain-link {
    display: grid; grid-template-columns: var(--db-space-7) minmax(0, 1fr); align-items: baseline; column-gap: var(--db-space-4); row-gap: var(--db-space-2);
    color: var(--db-ink); text-decoration: none; transform-origin: center; opacity: 0;
    transform: perspective(1000px) translateZ(-90px) rotateX(-5deg) scale(0.96);
    transition: transform var(--db-andante) var(--db-exhale), opacity var(--db-moderato), color var(--db-allegro);
  }
  .db-curtain[open] .db-curtain-link { opacity: 1; transform: none; transition-delay: calc(var(--db-moderato) + var(--db-curtain-order, 0) * var(--db-arpeggio)); }
  @starting-style { .db-curtain[open] .db-curtain-link { opacity: 0; transform: perspective(1000px) translateZ(-90px) rotateX(-5deg) scale(0.96); } }
  .db-curtain-number { grid-column: 1; grid-row: 1; direction: ltr; unicode-bidi: isolate; font-size: var(--db-pp); color: var(--db-pencil); }
  .db-curtain-name { grid-column: 2; font-size: var(--db-ff); line-height: var(--db-ff-lh); letter-spacing: var(--db-ff-tr); font-weight: 300; overflow-wrap: anywhere; }
  .db-curtain-description { grid-column: 2; font-family: var(--db-expression); font-style: italic; font-size: var(--db-p); }
  .db-curtain-link:is(:hover, [data-force~="hover"]) .db-curtain-name { text-decoration: underline; text-decoration-thickness: var(--db-hairline); text-underline-offset: 0.12em; }
  .db-curtain-close:focus-visible, .db-curtain-link:focus-visible { outline: var(--db-stroke) solid var(--db-accent); outline-offset: var(--db-space-2); }
  @media (max-width: 40rem) {
    .db-curtain { padding-block-end: calc(var(--db-space-6) + env(safe-area-inset-bottom)); }
    .db-curtain-name { font-size: var(--db-f); line-height: var(--db-f-lh); letter-spacing: var(--db-f-tr); }
    .db-curtain-link { grid-template-columns: var(--db-space-4) minmax(0, 1fr); }
    [data-curtain-far] { transform: perspective(1000px) rotateX(2deg) translateZ(-40px) scale(0.98); }
  }
  @media (prefers-reduced-motion: reduce) {
    [data-curtain-far], .db-curtain .db-curtain-link { transform: none; }
    .db-curtain, .db-curtain::backdrop, .db-curtain .db-curtain-link { transition-duration: 120ms; transition-delay: 0ms; }
    @starting-style { .db-curtain[open] .db-curtain-link { transform: none; } }
  }
  @media (forced-colors: active) { .db-curtain { color: CanvasText; } .db-curtain::backdrop { background: Canvas; } .db-curtain-link { color: LinkText; } }
}
